content:
{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Participant provides signed informed consent to participate in this study, which includes compliance with the requirements and restrictions listed in the Informed Consent Form and in this protocol.",
      "quote": "Participant provides signed informed consent (as described in Appendix 1) to participate in this study, which includes compliance with the requirements and restrictions listed in the Informed Consent Form and in this protocol."
    },
    {
      "kind": "inclusion",
      "text": "Participant must be age ≥18 years at the time of signing Informed Consent Form.",
      "quote": "Participant must be age ≥18 years at the time of signing Informed Consent Form.",
      "thresholds": [
        {
          "test": "age",
          "op": ">=",
          "value": 18,
          "unit": "years"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Participant has pathologically or cytologically confirmed, definitively diagnosed, locally advanced unresectable NSCLC (Stage IIIB not eligible for definitive chemoradiotherapy) or metastatic NSCLC (Stage IV), per the Union Internationale Contre le Cancer/American Joint Committee on Cancer staging system (Amin et al. 2017) of either squamous or non-squamous histology based on the major histologic component that has not been treated with systemic anticancer therapy for metastatic disease.",
      "quote": "Participant has pathologically or cytologically confirmed, definitively diagnosed, locally advanced unresectable NSCLC (i.e., Stage IIIB not eligible for definitive chemoradiotherapy) or metastatic NSCLC (i.e., Stage IV), per the Union Internationale Contre le Cancer/American Joint Committee on Cancer staging system (Amin et al. 2017) of either squamous or non-squamous histology based on the major histologic component that has not been treated with systemic anticancer therapy for metastatic disease."
    },
    {
      "kind": "inclusion",
      "text": "Participant has documented RET fusion that meets one of the following two criteria: (1) Documented RET fusion using either tissue or plasma, as determined by an appropriate validated local test performed by a CLIA-certified or equivalent accredited diagnostic laboratory; (2) Documented RET fusion by a positive result from tumor tissue testing performed centrally by Foundation Medicine (FMI) clinical trial assay or an alternate, approved central laboratory for that region.",
      "quote": "Participant has documented RET fusion that meets one of the following two criteria: – Documented RET fusion using either tissue or plasma, as determined by an appropriate validated local test performed by a Clinical Laboratory Improvement Amendments (CLIA)-certified or equivalent accredited diagnostic laboratory. – Documented RET fusion by a positive result from tumor tissue testing performed centrally by Foundation Medicine (FMI) clinical trial assay or an alternate, approved central laboratory for that region."
    },
    {
      "kind": "inclusion",
      "text": "The participant agrees to provide preferably adequate tumor tissue (archived, if available, or a fresh biopsy) or if tumor tissue cannot be obtained, a fixed and embedded cell pellet from pleural effusion would be acceptable for central confirmation of RET fusion status using an NGS-based assay. If no adequate tumor material is available and a new biopsy is not feasible, the participant will not be eligible for enrollment. This specimen must be accompanied by the full laboratory report of the RET fusion local test and must also be submitted within 2 weeks of enrollment for confirmation of RET status by central testing.",
      "quote": "The participant agrees to provide preferably adequate tumor tissue (archived, if available, or a fresh biopsy) or if tumor tissue cannot be obtained, a fixed and embedded cell pellet from pleural effusion would be acceptable for central confirmation of RET fusion status using an NGS-based assay. If no adequate tumor material is available and a new biopsy is not feasible, the participant will not be eligible for enrollment. This specimen must be accompanied by the full laboratory report of the RET fusion local test and must also be submitted within 2 weeks of enrollment for confirmation of RET status by central testing."
    },
    {
      "kind": "inclusion",
      "text": "A representative formalin-fixed, paraffin-embedded (FFPE) tumor specimen in a paraffin block (preferred) or a target of 15-20 slides containing unstained, freshly cut, serial sections is required for participation in this study. A minimum of 10-14 slides is acceptable if the slides meet the tissue requirements in Section 8.10. Notify the Medical Monitor if less than 15 slides are available.",
      "quote": "A representative formalin-fixed, paraffin-embedded (FFPE) tumor specimen in a paraffin block (preferred) or a target of 15-20 slides containing unstained, freshly cut, serial sections is required for participation in this study. – A minimum of 10-14 slides is acceptable if the slides meet the tissue requirements in Section 8.10. Notify the Medical Monitor if less than 15 slides are available."
    },
    {
      "kind": "inclusion",
      "text": "Participant has an ECOG Performance Status 0 or 1.",
      "quote": "Participant has an ECOG Performance Status 0 or 1 (see Appendix 7)."
    },
    {
      "kind": "inclusion",
      "text": "Participants who have a negative HIV test at screening, with the following exception: Individuals with a positive HIV test at screening are eligible, provided they are stable on anti-retroviral therapy, have a CD4 count ≥ 200/µL, and have an undetectable viral load.",
      "quote": "Participants who have a negative HIV test at screening, with the following exception: Individuals with a positive HIV test at screening are eligible, provided they are stable on anti-retroviral therapy, have a CD4 count ≥ 200/µL, and have an undetectable viral load.",
      "thresholds": [
        {
          "test": "CD4 count",
          "op": ">=",
          "value": 200,
          "unit": "/µL"
        }
      ]
    },
    {
      "kind": "inclusion",
      "text": "Participant has measurable disease, as determined by the local site investigator or radiologic assessment according to RECIST v1.1. Lesions located in a previously irradiated area are considered measurable if progression has been demonstrated after irradiation.",
      "quote": "Participant has measurable disease, as determined by the local site investigator or radiologic assessment according to RECIST v1.1 (see Appendix 8). – Lesions located in a previously irradiated area are considered measurable if progression has been demonstrated after irradiation."
    },
    {
      "kind": "inclusion",
      "text": "Participant cannot have received any prior anticancer therapy for metastatic disease. Participants can have received previous anticancer therapy (except a selective RET inhibitor) in the neoadjuvant or adjuvant setting but must have experienced an interval of at least ≥6 months from completion of therapy to recurrence. Participants who have received previous immune checkpoint inhibitors in the adjuvant setting or consolidation therapy following chemoradiation are not allowed to receive pembrolizumab if randomized to Arm B.",
      "quote": "Participant cannot have received any prior anticancer therapy for metastatic disease. – Participants can have received previous anticancer therapy (except a selective RET inhibitor) in the neoadjuvant or adjuvant setting but must have experienced an interval of at least ≥6 months from completion of therapy to recurrence. – Participants who have received previous immune checkpoint inhibitors in the adjuvant setting or consolidation therapy following chemoradiation are not allowed to receive pembrolizumab if randomized to Arm B."
    },
    {
      "kind": "inclusion",
      "text": "Participant is an appropriate candidate for and agrees to receive one of the investigator choice platinum-based anticancer regimens if randomized to Arm B.",
      "quote": "Participant is an appropriate candidate for and agrees to receive one of the investigator choice platinum-based anticancer regimens if randomized to Arm B."
    },
    {
      "kind": "inclusion",
      "text": "For women of childbearing potential: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraception, as defined below: Women must remain abstinent or use a highly effective method of non-hormonal contraception with a failure rate of <1% per year during the treatment period and for a period of a minimum of 14 days after the final dose of pralsetinib. The duration of contraceptive methods for participants receiving SOC platinum-containing anticancer treatment regimens is as indicated in the respective applicable labeling documents.",
      "quote": "For women of childbearing potential: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraception, as defined below: – Women must remain abstinent or use a highly effective method of non-hormonal contraception with a failure rate of <1% per year during the treatment period and for a period of a minimum of 14 days after the final dose of pralsetinib. The duration of contraceptive methods for participants receiving SOC platinum-containing anticancer treatment regimens is as indicated in the respective applicable labeling documents (refer to Appendix 4, Section A4–1)."
    },
    {
      "kind": "inclusion",
      "text": "For men: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraceptive methods, and agree to refrain from donating sperm, as defined below: With a female partner of childbearing potential who is not pregnant, men who are not surgically sterile must remain abstinent or use a condom plus an additional contraceptive method that together result in a failure rate of < 1% per year, during the treatment period and for 7 days after the final dose of pralsetinib to avoid exposing the embryo. With pregnant female partners, men must remain abstinent or use a condom during the treatment period and for at least 7 days after the final dose of pralsetinib to avoid exposing the embryo. Men must refrain from donating sperm during this same period.",
      "quote": "For men: participants who agree to remain abstinent (refrain from heterosexual intercourse) or use contraceptive methods, and agree to refrain from donating sperm, as defined below: – With a female partner of childbearing potential who is not pregnant, men who are not surgically sterile must remain abstinent or use a condom plus an additional contraceptive method that together result in a failure rate of < 1% per year, during the treatment period and for 7 days after the final dose of pralsetinib to avoid exposing the embryo. With pregnant female partners, men must remain abstinent or use a condom during the treatment period and for at least 7 days after the final dose of pralsetinib to avoid exposing the embryo. Men must refrain from donating sperm during this same period."
    }
  ]
}
